FSW = fcmp(s2, s1)
EAX = bor(band(EAX, 0xffff0000), FSW)
do local r = band(band(EAX, 16640), 4294967295)
FZ = r == 0
EAX = r
end
if not FZ then pc = 2 else pc = 1 end
elseif pc == 1 then
EAX = 0
wu(M, band(ECX) - 7245824, 1065353216)
wu(M, band(ECX + 4) - 7245824, EAX)
wu(M, band(ECX + 8) - 7245824, EAX)
ESP = ESP + 4
do return end
elseif pc == 2 then
s0 = rf(M, 2008) / s0
s1 = s0
s1 = s1 * rf(M, band(ECX) - 7245824)
wfd(band(ECX) - 7245824, s1)
s1 = s0
s1 = s1 * rf(M, band(ECX + 4) - 7245824)
wfd(band(ECX + 4) - 7245824, s1)
s0 = s0 * rf(M, band(ECX + 8) - 7245824)
wfd(band(ECX + 8) - 7245824, s0)
ESP = ESP + 4
do return end
end
end
end

-- registers are per module: calls between modules go through the shared register file ctx.R
local R = ctx.R
local function LOAD() EAX, EBX, ECX, EDX, ESI, EDI, EBP, ESP, FT, FSW = R[1], R[2], R[3], R[4], R[5], R[6], R[7], R[8], R[9], R[10] end
local function SAVE() R[1], R[2], R[3], R[4], R[5], R[6], R[7], R[8], R[9], R[10] = EAX, EBX, ECX, EDX, ESI, EDI, EBP, ESP, FT, FSW end
for a, f in pairs(XF) do
	ctx.XF[a] = function() LOAD(); f(); SAVE() end
end
setmetatable(XF, {__index = function(t, a)
	local g = ctx.XF[a]
	if not g then error(string.format("NR2003 build: call to unknown %08x", a)) end
	local s = function() SAVE(); g(); LOAD() end
	t[a] = s
	return s
end})
end

]=])
print("PATCH_STAGE10 parte 2/4 guardada (3 módulos). Próximo: parte 3")
